import{z as B,x as A,o as E,c as d,q as o,j as r,D as e,d as n,s as l,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"诊断性预期","description":"","frontmatter":{"title":"诊断性预期","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/diagnostic-expectations.md","filePath":"econ/diagnostic-expectations.md","lastUpdated":1791063341000}'),p={name:"econ/diagnostic-expectations.md"};function h(m,a,c,D,f,_){const i=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=o('<h1 id="诊断性预期" tabindex="-1">诊断性预期 <a class="header-anchor" href="#诊断性预期" aria-label="Permalink to &quot;诊断性预期&quot;">​</a></h1><div class="epigraph"><p>代表性启发使人按「多像」来加权状态：新闻之后，条件分布被过度代表，预期过度反应，随后均值回复。</p><footer>—— Bordalo, Gennaioli and Shleifer, Diagnostic Expectations and Credit Cycles, JFinance 2018；Kahneman and Tversky 的代表性</footer></div><p><a href="/econ/rational-inattention">上一课</a>的误差是最优噪声。本课缺口是<strong>有方向的偏差</strong>：诊断性预期。不重写 Shannon 容量，不把行为金融的全部偏差清单搬进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>粘性信息与疏忽偏向反应不足。信贷与股市常有反应过度与崩溃。Bordalo–Gennaioli–Shleifer：把 Kahneman–Tversky 的代表性写成对真实条件分布的扭曲：</p> \\[\\mathbb{E}^\\theta[x_{t+1}\\mid I_t]\\propto \\mathbb{E}[x_{t+1}\\mid I_t]\\left(\\frac{p(I_t\\mid\\text{典型})}{p(I_t)}\\right)^\\theta. \\]<p>好消息使「好状态」显得更代表，预报过冲，下一期修正。缺口是给宏观与信贷周期一条过度反应装置，与学习的外推相关但微观基础不同。</p><p><span class="marginnote">Bordalo, Gennaioli and Shleifer, <em>Journal of Finance</em> 2018。BGS 对宏观诊断性预期的后续。Gennaioli and Shleifer, <em>A Crisis of Beliefs</em>。本课不写限价簿上的行为做市。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在 NK 或信贷模型里把 \\(\\mathbb{E}\\) 换成诊断性 \\(\\mathbb{E}^\\theta\\)。脉冲：冲击后预期过冲，实现不及预期，出现反转。调查：预期修正对实现的回归系数可大于 RE（Coibion–Gorodnichenko 的反应不足是另一侧；诊断性瞄准过冲的序列）。信贷：对违约率的诊断性预报制造利差过窄再突然变宽。</p>',10)),(E(),r(s,null,{default:e(()=>[l(i,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEWS%5B%22%E6%96%B0%E9%97%BB%22%5D%20--%3E%20REP%5B%22%E4%BB%A3%E8%A1%A8%E6%80%A7%E5%8A%A0%E6%9D%83%22%5D%0A%20%20REP%20--%3E%20OVER%5B%22%E9%A2%84%E6%9C%9F%E8%BF%87%E5%86%B2%22%5D%0A%20%20OVER%20--%3E%20REV%5B%22%E5%AE%9E%E7%8E%B0%E5%90%8E%E4%BF%AE%E6%AD%A3%22%5D%0A%20%20REV%20--%3E%20CYC%5B%22%E4%BF%A1%E8%B4%B7%20%2F%20%E5%AE%8F%E8%A7%82%E5%91%A8%E6%9C%9F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"与适应性学习：学习也可以外推，但是渐近可到 RE；诊断性在 \\(\\theta\\gt 0\\) 时系统偏离贝叶斯，即使参数已知。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[n("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"机制是似然比扭曲，不是容量不够。因此「更重要的变量」也会被过度代表，不会因为重要而变准——与疏忽相反。政策沟通：生动的情景可能加大 \\(\\theta\\) 方向的权重，稳定沟通需要避免代表性叙事——后课管理。HANK：若高 MPC 家庭诊断性外推收入，间接效应过冲更强。",-1)),(E(),r(s,null,{default:e(()=>[l(i,{id:"mermaid-36",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%90%8C%E4%B8%80%E5%88%A9%E5%A5%BD%E5%86%B2%E5%87%BB%22%5D%20--%3E%20RE%5B%22%E7%90%86%E6%80%A7%E9%A2%84%E6%9C%9F%3A%20%E6%8C%89%E6%9D%A1%E4%BB%B6%E5%88%86%E5%B8%83%E9%A2%84%E6%B5%8B%22%5D%0A%20%20S%20--%3E%20DE%5B%22%E8%AF%8A%E6%96%AD%E6%80%A7%E9%A2%84%E6%9C%9F%3A%20%E5%A5%BD%E7%8A%B6%E6%80%81%E8%A2%AB%E8%BF%87%E5%BA%A6%E4%BB%A3%E8%A1%A8%22%5D%0A%20%20RE%20--%3E%20ON%5B%22%E9%A2%84%E6%B5%8B%E8%B4%B4%E7%9D%80%E7%9C%9F%E5%AE%9E%E5%9D%87%E5%80%BC%22%5D%0A%20%20DE%20--%3E%20OS%5B%22%E9%A2%84%E6%B5%8B%E8%BF%87%E5%86%B2%3A%20%E9%AB%98%E4%BA%8E%E7%9C%9F%E5%AE%9E%E5%9D%87%E5%80%BC%22%5D%0A%20%20OS%20--%3E%20MISS%5B%22%E5%AE%9E%E7%8E%B0%E4%B8%8D%E5%8F%8A%E9%A2%84%E6%B5%8B%22%5D%0A%20%20MISS%20--%3E%20CORR%5B%22%E4%B8%8B%E6%9C%9F%E5%90%91%E4%B8%8B%E4%BF%AE%E6%AD%A3%3A%20%E5%9D%87%E5%80%BC%E5%9B%9E%E5%A4%8D%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">公式里的似然比代入个数：若好消息之后「好状态」的概率被抬到 0.8，而好状态在总体里本来只占 0.3，似然比就是 \\(0.8/0.3 \\approx 2.7\\)——预期被放大近三倍再加权，这就是过冲的算术来源。</span></p><p><span class="marginnote">直觉类比：诊断性预期像看完鲨鱼袭击的新闻就不敢下海——被咬的真实概率没变，只是「被咬」这个状态此刻太典型，人把它的权重临时调高；几周后新闻淡了，又觉得完全安全。过冲与修正是一个动作的两半。</span></p><p><span class="marginnote">诊断性不是唯一的过度反应模型（外推信念、自然预期 Fuster–Laibson–Mendel）。本课用 BGS 作为本课序的钉子。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有资产定价异象归因于 \\(\\theta\\)。不估计实验室的代表性参数当宏观唯一校准。新闻冲击（下一课）可以是基本面的提前信息，不必是偏差。不确定性冲击是方差，不是代表性。</p><p><span class="marginnote">常见误区：把 \\(\\theta\\) 读成「信息不够」造成的误差。\\(\\theta\\) 的扭曲与信息量无关——即使参数全部已知、数据无限多，只要 \\(\\theta \\gt 0\\)，预期仍系统偏离贝叶斯。它和疏忽模型的「容量不够」是两种不同的病。</span></p><p>后课默认：反应过度可用诊断性 \\(\\mathbb{E}^\\theta\\)；与疏忽的反应不足是不同参数。下一课：即使信念是 RE，提前到来的消息也会先动后验。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>诊断性预期：代表性启发扭曲条件分布，新闻后过冲再回复。</li><li>与最优噪声、与学习外推分列。</li><li>信贷利差与宏观预期修正是自然靶。</li><li>出处：Bordalo, Gennaioli and Shleifer, <em>JF</em> 2018。</li></ul>',9))])}const u=B(p,[["render",h]]);export{S as __pageData,u as default};
